from django.db import migrations, models


def activate_first_lead_form(apps, schema_editor):
    """The active lead form used to live in each browser; nothing on the server
    says which one it was. Switch on each client's oldest lead form so Create
    Lead keeps working after the upgrade instead of being blocked for everyone."""
    Form = apps.get_model("crm", "Form")
    seen = set()
    for form in Form.objects.filter(kind="lead", deleted_at__isnull=True).order_by("client_id", "created_at"):
        if form.client_id in seen:
            continue
        seen.add(form.client_id)
        Form.objects.filter(pk=form.pk).update(is_active=True)


